function i(t){if(!t)return"—";const n=Date.parse(t);if(Number.isNaN(n))return"—";const r=Math.round((Date.now()-n)/1e3);if(r<0||r<45)return"just now";if(r<90)return"1m ago";const e=Math.round(r/60);if(e<60)return`${e}m ago`;const u=Math.round(e/60);if(u<24)return`${u}h ago`;const o=Math.round(u/24);if(o<30)return`${o}d ago`;const a=Math.round(o/30);return a<12?`${a}mo ago`:`${Math.round(a/12)}y ago`}function s(t){if(!t)return"—";const n=Date.parse(t);if(Number.isNaN(n))return"—";const r=Math.round((n-Date.now())/1e3);if(r<=0)return"expired";if(r<60)return`in ${r}s`;const e=Math.round(r/60);if(e<60)return`in ${e}m`;const u=Math.round(e/60);if(u<24)return`in ${u}h`;const o=Math.round(u/24);return o<30?`in ${o}d`:`in ${Math.round(o/30)}mo`}function f(t){if(!t)return"";const n=new Date(t);return Number.isNaN(n.getTime())?"":n.toISOString().replace("T"," ").replace(/\.\d+Z$/," UTC")}export{f as a,i as r,s as t};
